  "inlineSchema": "// Schéma Prisma — LAS Inspections API\n//\n// Miroir aussi fidèle que possible des types déjà établis côté frontend\n// (src/lib/mock-data.ts, inspection-checklist.ts, fiche-catalog.ts,\n// building-checklist.ts, user-directory.ts, task-status.ts) pour que la\n// migration du localStorage vers le backend soit directe.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  admin\n  supervisor\n}\n\nenum TaskStatus {\n  not_submitted\n  in_progress\n  pending // \"En attente de vérification\"\n  verified\n}\n\nenum TaskKind {\n  horizontal\n  batiment\n}\n\n/// Compte utilisateur — voir src/lib/user-directory.ts côté frontend.\nmodel User {\n  id           String   @id @default(cuid())\n  name         String\n  username     String   @unique\n  email        String   @unique\n  passwordHash String\n  role         Role     @default(supervisor)\n  /// Groupes de supervision (ex. \"Supervisor 1\") — un utilisateur peut en avoir plusieurs.\n  groups       String[]\n  initials     String\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  submissions  Submission[]\n  tasksCreated Task[]       @relation(\"TaskCreatedBy\")\n\n  @@map(\"users\")\n}\n\n/// Tâche d'inspection assignée — voir src/lib/mock-data.ts#TaskRow côté frontend.\nmodel Task {\n  id       String     @id @default(cuid())\n  form     String\n  dueDate  DateTime\n  zone     String\n  notes    String     @default(\"\")\n  group    String\n  /// Dénormalisés pour retrouver exactement les filtres front (année/bimestre/semaine)\n  /// sans recalcul ambigu côté client.\n  year     Int\n  bimester Int\n  week     Int\n  status   TaskStatus @default(not_submitted)\n  kind     TaskKind   @default(horizontal)\n\n  createdById String?\n  createdBy   User?   @relation(\"TaskCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  submissions Submission[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([group, status])\n  @@index([form])\n  @@map(\"tasks\")\n}\n\n/// Fiche soumise — en-tête + liste de constats en JSON (structure proche de\n/// PointState côté frontend). Les photos sont stockées séparément (table Photo)\n/// pour garantir des URLs stables (sprint \"stockage objets fiable\").\nmodel Submission {\n  id     String   @id @default(cuid())\n  task   Task     @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  taskId String\n  kind   TaskKind\n\n  form  String\n  zone  String\n  notes String @default(\"\")\n  group String\n\n  /// Uniquement pour les fiches bâtiment.\n  sector     String?\n  compliance String?\n\n  comment String @default(\"\")\n\n  /// Liste des constats en défaut : { segment?, category, point, severity,\n  /// qualitatif, localisation, actionCorrective, photoIds: string[] }[]\n  defects Json\n\n  /// Numéro(s) de version des dictionnaires en vigueur à la soumission —\n  /// traçabilité \"une fiche déjà soumise n'est pas altérée rétroactivement\".\n  modelVersion Json\n\n  submittedBy   User     @relation(fields: [submittedById], references: [id])\n  submittedById String\n  submittedAt   DateTime @default(now())\n\n  photos Photo[]\n\n  createdAt DateTime @default(now())\n\n  @@index([taskId])\n  @@index([submittedAt])\n  @@map(\"submissions\")\n}\n\n/// Photo attachée à un constat — fichier stocké (disque pour l'instant,\n/// S3/R2 prévu) + URL stable et servie publiquement.\nmodel Photo {\n  id           String     @id @default(cuid())\n  submission   Submission @relation(fields: [submissionId], references: [id], onDelete: Cascade)\n  submissionId String\n  /// Identifie à quel point/item de la fiche cette photo appartient (id de constat).\n  constatKey   String\n  /// Chemin relatif sur le disque (ou clé objet une fois migré vers S3/R2).\n  storageKey   String\n  /// URL publique stable — jamais de localhost codé en dur côté client.\n  url          String\n  mimeType     String\n  sizeBytes    Int\n  createdAt    DateTime   @default(now())\n\n  @@index([submissionId])\n  @@map(\"photos\")\n}\n\n/// Dictionnaire versionné (familles/dégradations, catalogue de fiches, checklist\n/// bâtiment) — même principe que src/lib/dictionary-store.ts côté frontend :\n/// une ligne par clé, données en JSON, version incrémentée à chaque écriture.\n\nmodel DictionaryEntry {\n  id        String   @id @default(cuid())\n  key       String\n  data      Json\n  version   Int\n  createdAt DateTime @default(now())\n\n  @@unique([key, version])\n  @@index([key])\n  @@map(\"dictionary_entries\")\n}\n",
